import icontract
from typing import List


def is_even(n: int) -> bool:
    return n % 2 == 0


def is_odd(n: int) -> bool:
    return n % 2 != 0


def first_even(a: List[int]) -> int:
    """The first even element of a (0 if there is none)."""
    for x in a:
        if is_even(x):
            return x
    return 0


def first_odd(a: List[int]) -> int:
    """The first odd element of a (0 if there is none)."""
    for x in a:
        if is_odd(x):
            return x
    return 0


@icontract.require(lambda a: len(a) > 1)
@icontract.require(lambda a: any(is_even(x) for x in a))
@icontract.require(lambda a: any(is_odd(x) for x in a))
@icontract.ensure(lambda a, result: result == first_even(a) - first_odd(a))
def firstEvenOddDifference(a: List[int]) -> int:
    e = 0
    while not is_even(a[e]):
        e += 1
    o = 0
    while not is_odd(a[o]):
        o += 1
    return a[e] - a[o]
